import { HERO_SCENE_VIEWBOX, heroSceneLayers } from "./hero-scene.generated";

// Separate <svg> layers: the towers fade in far to near, then the network draws
// itself path by path (its own delays). Keeping the network in its own layer
// means only it repaints while drawing.
const layers = [
  { key: "far", className: "hero-layer", delay: 0 },
  { key: "mid", className: "hero-layer", delay: 150 },
  { key: "near", className: "hero-layer", delay: 300 },
  { key: "network", className: "", delay: 0 },
] as const;

/** Illustrative drafting scene, generated by scripts/generate-hero-wireframe.mjs. */
export function HeroScene({ className }: { className: string }) {
  return (
    <div aria-hidden className={className}>
      {layers.map(({ key, className: layerClass, delay }) => (
        <svg
          key={key}
          viewBox={HERO_SCENE_VIEWBOX}
          preserveAspectRatio="xMaxYMax slice"
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
          className={`absolute inset-0 h-full w-full ${layerClass}`}
          style={delay ? { animationDelay: `${delay}ms` } : undefined}
          dangerouslySetInnerHTML={{ __html: heroSceneLayers[key] }}
        />
      ))}
    </div>
  );
}
